import{_ as i,o as e,c as a,an as n}from"./chunks/framework.BlqdX2Ok.js";const c=JSON.parse('{"title":"Kernel Fusion","description":"","frontmatter":{},"headers":[],"relativePath":"perf/kernel_fusion.md","filePath":"perf/kernel_fusion.md","lastUpdated":null}'),t={name:"perf/kernel_fusion.md"};function l(h,s,p,r,o,d){return e(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="Kernel-Fusion" tabindex="-1">Kernel Fusion <a class="header-anchor" href="#Kernel-Fusion" aria-label="Permalink to &quot;Kernel Fusion {#Kernel-Fusion}&quot;">​</a></h1><p>On CUDA, nested broadcast expressions are fused into a single PTX kernel when fusion is enabled (the default). There is no separate <code>@fuse</code> macro. You write ordinary Julia broadcast code, and cuNumeric compiles eligible trees into one kernel instead of launching one op at a time.</p><p>Prefer Julia&#39;s <code>@.</code> macro for multi-op elementwise expressions. Placing <code>.</code> on every operator by hand is easy to get wrong: missing a dot on unary negation or addition silently changes the meaning, and it can also break fusion by splitting work into the wrong ops.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Easy to miss the dot on negation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> .-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prefer: @. dots every operator, which is clearer and fusion-friendly</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c</span></span></code></pre></div><p>Fusion applies when CUDA is available, the array leaves share the same shape, and the expression has at least <code>FUSE_BROADCAST_MIN_OPS</code> ops (default 2). Otherwise cuNumeric falls back to evaluating one op at a time. Shape-mismatched broadcasts such as <code>matrix .+ vector</code> use the unfused path.</p><p>Toggle fusion through <code>CNPreferences</code> (restart Julia after changing these):</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CNPreferences</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">enable_broadcast_fusion!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">disable_broadcast_fusion!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_broadcast_fusion_min_ops!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CNPreferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_broadcast_fusion_min_ops!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># also fuse single-ops</span></span></code></pre></div><p>What <code>set_broadcast_fusion_min_ops!</code> controls:</p><ul><li><p><strong><code>2</code> (default):</strong> only trees with two or more ops fuse. Example: <code>y .= @. a * b + c</code> can fuse; <code>y .= cos.(x)</code> does not. Keeping single-ops on the unfused C-API path avoids PTX compile overhead when there is little to gain.</p></li><li><p><strong><code>1</code>:</strong> every eligible broadcast can fuse, including unary / single-op forms. Prefer this when you want uniform fused behavior (for example in tests) rather than for typical apps.</p></li></ul><p>The threshold counts <code>Broadcasted</code> nodes in the expression tree. Set it through <code>CNPreferences</code>, then restart Julia. See <a href="./../api_preferences">CNPreferences</a>.</p><p>To inspect a fused launch or a lifetime rewrite, see <a href="./../debugging">Debugging</a>. For the implementation pipeline, see <a href="./../internals">Internals</a>.</p>`,11)])])}const g=i(t,[["render",l]]);export{c as __pageData,g as default};
